import static org.mockito.Mockito.when;

public class CssFormatterTest {

    @Test
    public void initEmptyOptions() {
        final CssFormatter formatter = new CssFormatter();
        final Map<String, String> options = new java.util.HashMap<>();
        when(formatter.getConfigurationSource()).thenReturn(new ConfigurationSource());
        formatter.init(options, null);
        assertTrue(formatter.isInitialized());
    }

    @Test
    public void doFormatSimpleString() throws IOException {
        final String input = "body { background-color: #f2f2f2; }";
        final CssFormatter formatter = new CssFormatter();
        when(formatter.getConfigurationSource()).thenReturn(new ConfigurationSource());
        assertEquals("body {\n  background-color: #f2f2f2;\n}", formatter.doFormat(input, LineEnding.LF));
    }

    @Test
    public void doFormatStringWithComment() throws IOException {
        final String input = "/* This is a comment */ body { background-color: #f2f2f2; }";
        final CssFormatter formatter = new CssFormatter();
        when(formatter.getConfigurationSource()).thenReturn(new ConfigurationSource());
        assertEquals("body {\n  /* This is a comment */\n  background-color: #f2f2f2;\n}", formatter.doFormat(input, LineEnding.LF));
    }

    @Test
    public void doFormatStringWithMultipleLines() throws IOException {
        final String input = "body {\n  background-color: #f2f2f2;\n\nh1 { color: #000; }";
        final CssFormatter formatter = new CssFormatter();
        when(formatter.getConfigurationSource()).thenReturn(new ConfigurationSource());
        assertEquals("body {\n  background-color: #f2f2f2;\n\n  h1 {\n    color: #000;\n  }\n}", formatter.doFormat(input, LineEnding.LF));
    }

    @Test
